class Solution {
    public int minSubArrayLen(int target, int[] nums) {
        int best = Integer.MAX_VALUE;
        long sum = 0;
        int left = 0;

        for (int right = 0; right < nums.length; right++) {
            sum += nums[right];
            while (sum >= target) {
                best = Math.min(best, right - left + 1);
                sum -= nums[left];
                left++;
            }
        }

        return best == Integer.MAX_VALUE ? 0 : best;
    }
}

class Solution {
    public int minSubArrayLen(int target, int[] nums) {
        int n = nums.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        int best = Integer.MAX_VALUE;
        for (int start = 0; start < n; start++) {
            long needed = prefix[start] + target;
            int end = lowerBound(prefix, needed);
            if (end <= n) {
                best = Math.min(best, end - start);
            }
        }

        return best == Integer.MAX_VALUE ? 0 : best;
    }

    private int lowerBound(long[] prefix, long target) {
        int left = 0;
        int right = prefix.length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (prefix[mid] >= target) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }
}

class Solution {
    public int minSubArrayLen(int target, int[] nums) {
        int left = 1;
        int right = nums.length;
        int answer = 0;

        while (left <= right) {
            int length = left + (right - left) / 2;
            if (hasWindowAtLeast(target, nums, length)) {
                answer = length;
                right = length - 1;
            } else {
                left = length + 1;
            }
        }

        return answer;
    }

    private boolean hasWindowAtLeast(int target, int[] nums, int length) {
        long sum = 0;
        for (int right = 0; right < nums.length; right++) {
            sum += nums[right];
            if (right >= length) {
                sum -= nums[right - length];
            }
            if (right >= length - 1 && sum >= target) {
                return true;
            }
        }
        return false;
    }
}

class Solution {
    public int minSubArrayLen(int target, int[] nums) {
        int best = Integer.MAX_VALUE;

        for (int start = 0; start < nums.length; start++) {
            long sum = 0;
            for (int end = start; end < nums.length; end++) {
                sum += nums[end];
                if (sum >= target) {
                    best = Math.min(best, end - start + 1);
                    break;
                }
            }
        }

        return best == Integer.MAX_VALUE ? 0 : best;
    }
}
